for o in $(seq 0 12 384); do curl -s -G "$B" --data-urlencode offset=$o -o sa_$o.json; done
python3 -I -c "
import json,collections
s={}
for o in range(0,396,12):
    for h in json.load(open(f'sa_{o}.json'))['hits']: s[h['button']['buttonLink']['url']]=h['tags'][0]['tagText']
print(len(s),collections.Counter(s.values()))"

